set-variable.value:
@{
            switch (context.Operation.Id) {
                case "get_loan_details":           return "Loans.Read|ReadOnly,Servicer,SeniorServicer|none|60";
                case "get_payment_history":        return "Loans.Read|ReadOnly,Servicer,SeniorServicer|none|60";
                case "get_credit_report":          return "Loans.Credit|Servicer,SeniorServicer|none|3";
                case "update_income_verification": return "Loans.Income|Servicer,SeniorServicer|if_tainted|10";
                case "create_payment_deferral":    return "Loans.Deferral|Servicer,SeniorServicer|required|5";
                case "waive_late_fee":             return "Loans.Waiver|SeniorServicer|required|5";
                default:                           return "";
            }
        }

@{
            var jwt = (Jwt)context.Variables["jwt"];
            var azp = string.Join("", jwt.Claims.GetValueOrDefault("azp", new string[0]));
            if (azp != "{{agent-client-id}}") { return "unauthorized_client"; }
            var runId = context.Request.Headers.GetValueOrDefault("X-Agent-Run-Id", "");
            if (runId.Length == 0 || runId.Length > 128) { return "missing_run_id"; }
            var rule = (string)context.Variables["rule"];
            if (rule == "") { return "unknown_operation"; }
            var parts = rule.Split('|');
            var scopes = string.Join(" ", jwt.Claims.GetValueOrDefault("scp", new string[0])).Split(' ');
            if (!scopes.Contains(parts[0])) { return "insufficient_scope"; }
            var roles = jwt.Claims.GetValueOrDefault("roles", new string[0]);
            if (!parts[1].Split(',').Intersect(roles).Any()) { return "insufficient_entitlement"; }
            return "";
        }

@{
                    var c = (Jwt)context.Variables["ctx"];
                    var claimRun = string.Join("", c.Claims.GetValueOrDefault("run_id", new string[0]));
                    var hdrRun = context.Request.Headers.GetValueOrDefault("X-Agent-Run-Id", "");
                    if (claimRun != hdrRun) { return "mismatch"; }
                    var flag = string.Join("", c.Claims.GetValueOrDefault("untrusted_content", new string[0])).ToLower();
                    return flag == "true" ? "true" : "false";
                }

@{
            var mode = ((string)context.Variables["rule"]).Split('|')[2];
            var t = (string)context.Variables["tainted"] == "true";
            return (mode == "required" || (mode == "if_tainted" && t)) ? "true" : "false";
        }

send-request.set-body:
@{
                        var raw = context.Request.Body == null ? "" : context.Request.Body.As<string>(preserveContent: true);
                        return new JObject(
                            new JProperty("approval_id", context.Request.Headers.GetValueOrDefault("X-Approval-Id", "")),
                            new JProperty("method", context.Request.Method),
                            new JProperty("path", context.Request.OriginalUrl.Path),
                            new JProperty("query", context.Request.OriginalUrl.QueryString),
                            new JProperty("body", raw),
                            new JProperty("run_id", context.Request.Headers.GetValueOrDefault("X-Agent-Run-Id", ""))
                        ).ToString();
                    }

return-response.set-body:
@{
                                var r = (IResponse)context.Variables["approvalResp"];
                                if (r == null) { return "{\"error\":\"approval_service_unavailable\"}"; }
                                return r.Body.As<string>();
                            }
